---@class MonthSignData
MonthSignData = class("MonthSignInData")

function MonthSignData:initialize()
    self.dayNum = 0  --日
    self.receive = false --是否领取
    self.ifGet = false --是否可以领取 0可以1不
    self.ifRepair = false --是否可以补签 0可以1不
    self.ifbat = false --是否月卡特别日
end

---@param  msg SC_UserSignInfo
function MonthSignData:SetData(msg)
    self.dayNum = msg.dayNum  --日
    self.receive = msg.curStatus > 0   --领取状态 0未1领
    self.ifGet = msg.ifGet == 0  --是否可以领取 0可以1不
    self.ifRepair = msg.ifRepair == 0 --是否可以补签 0可以1不
    self.ifbat = msg.ifbat == 1 --是否月卡特别日
end